1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	/** Base premium of each insurable item type. */
5	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	};
10	
11	/** Initial assessment surcharge on a customer's first insurance. */
12	const FIRST_INSURANCE_RATE = 0.1;
13	
14	export type Scenario = {
15	  customer: { yearsWithMHPCO: number };
16	  steps: Step[];
17	};
18	
19	export type Step = {
20	  op: string;
21	  items: Item[];
22	};
23	
24	export type Item = Record<string, unknown>;
25	
26	export type Result = { premium: number };
27	
28	export type ScenarioOutcome = { results: Result[] };
29	
30	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
31	  const items = scenario.steps[0].items;
32	  const policyBasePremium = items.reduce(
33	    (sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type as string],
34	    0,
35	  );
36	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
37	  return {
38	    results: [
39	      { premium: policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE },
40	    ],
41	  };
42	};
43

